//go:build ignore

// 向量生成器：仅用于一次性生成回归测试中钉住的确切字节常量。
// 规范 JSON 在本文件内手工拼接，不依赖 consensus 包的编码。
package main

import (
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
)

func doc(contentB64, senderB64 string, seq, fee, expiry uint64, sigB64 string) string {
	s := fmt.Sprintf(`{"content":"%s","expiry":%d,"fee":%d,"sender":"%s","sequence":%d`, contentB64, expiry, fee, senderB64, seq)
	if sigB64 != "" {
		s += fmt.Sprintf(`,"signature":"%s"`, sigB64)
	}
	return s + "}"
}

func main() {
	seed := make([]byte, ed25519.SeedSize)
	for i := range seed {
		seed[i] = byte(i + 1)
	}
	priv := ed25519.NewKeyFromSeed(seed)
	pub := priv.Public().(ed25519.PublicKey)
	pubB := base64.StdEncoding.EncodeToString(pub)
	fmt.Println("pubB64:", pubB)

	show := func(name, contentB64 string, content []byte, seq, fee, expiry uint64) {
		d := doc(contentB64, pubB, seq, fee, expiry, "")
		msg := "consensus-lab-tx-v1\n" + d
		sig := ed25519.Sign(priv, []byte(msg))
		sigB := base64.StdEncoding.EncodeToString(sig)
		idDoc := doc(contentB64, pubB, seq, fee, expiry, sigB)
		sum := sha256.Sum256([]byte(idDoc))
		fmt.Printf("--- %s\n", name)
		fmt.Printf("msg: %q\n", msg)
		fmt.Printf("sigB64: %s\n", sigB)
		fmt.Printf("idDoc: %s\n", idDoc)
		fmt.Printf("id: %s\n", hex.EncodeToString(sum[:]))
		_ = content
	}

	show("hello", "aGVsbG8=", []byte("hello"), 7, 3, 99)
	show("empty", "", nil, 1, 0, 2)
	bin := []byte{0x00, 0xff, 0xfe, 0x61}
	show("binary", base64.StdEncoding.EncodeToString(bin), bin, 5, 0, 18446744073709551615)
	const max = ^uint64(0)
	show("maxuint", "//8=", []byte{0xff, 0xff}, max, max, max)
}

